def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # Extend a diagonal pair away from the rest of the colored pattern.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue

                # The two possible outward directions from this pair.
                ends = ((r - dr, c - dc, -dr, -dc),
                        (r2 + dr, c2 + dc, dr, dc))
                clear = []
                for er, ec, sr, sc in ends:
                    clear.append(0 <= er < h and 0 <= ec < w and grid[er][ec] == bg)

                if clear.count(True) != 1:
                    continue
                i = clear.index(True)
                er, ec, sr, sc = ends[i]
                while 0 <= er < h and 0 <= ec < w and grid[er][ec] == bg:
                    out[er][ec] = color
                    er += sr
                    ec += sc
    return out
